alter table public.external_data_datasets enable row level security; alter table public.external_import_jobs enable row level security; drop policy if exists admin_read_public_data_datasets on public.external_data_datasets; create policy admin_read_public_data_datasets on public.external_data_datasets for select to authenticated using (exists(select 1 from public.profiles p where p.id=auth.uid() and (p.is_admin=true or p.role::text in ('admin','super_admin','platform_admin','owner')))); drop policy if exists admin_read_import_jobs on public.external_import_jobs; create policy admin_read_import_jobs on public.external_import_jobs for select to authenticated using (exists(select 1 from public.profiles p where p.id=auth.uid() and (p.is_admin=true or p.role::text in ('admin','super_admin','platform_admin','owner'))));
